/** Types & helpers from OrderDetailModal.tsx */

export const TEAL = '#0d9488';
export const CARD_BG = '#f3f4f6';

export function formatOrderTotal(d) {
  const raw = d.order_total != null ? d.order_total : d.delivery_price;
  const n = parseFloat(String(raw).replace(/[^0-9.]/g, ''));
  if (!Number.isNaN(n)) {
    return `£${n.toFixed(2)}`;
  }
  return raw ? `£${raw}` : '£0.00';
}

export function formatOrderItemsLine(d) {
  if (d.items && d.items.length > 0) {
    return d.items
      .map((i) => `${i.name} X ${i.quantity != null ? i.quantity : 1}`)
      .join(', ');
  }
  if (d.restaurant && d.restaurant.name) {
    return `Order from ${d.restaurant.name}`;
  }
  return 'Items not listed';
}

export function orderIdDisplay(item) {
  if (item == null) {
    return '—';
  }
  if (item.order_number != null && String(item.order_number).trim() !== '') {
    return `#${item.order_number}`;
  }
  return `#${item.id}`;
}
