  <div class="page">
    <div v-if="loading" class="loading-container">
      <div class="spinner-teal" />
      <p class="loading-text">Loading orders...</p>
    </div>

    <div v-else class="scroll-wrap">
      <div
        class="scroll-view"
        :class="{ 'empty-scroll': deliveries.length === 0 }"
      >
        <template v-if="deliveries.length === 0">
          <div class="empty-container">
            <p class="empty-text">No ongoing orders</p>
            <p class="empty-subtext">
              Pull down to refresh and check for updates
            </p>
            <button type="button" class="refresh-btn" @click="onRefresh">
              Refresh
            </button>
          </div>
        </template>
        <template v-else>
          <div class="pager-bar">
            <button
              type="button"
              class="pager-button"
              :class="{ 'pager-button-disabled': !canGoPrev }"
              :disabled="!canGoPrev"
              @click="prev"
            >
              <span class="pager-inner">
                <span
                  class="pager-glyph"
                  :class="{ 'pager-glyph-disabled': !canGoPrev }"
                  >◀</span
                >
                <span
                  class="pager-text"
                  :class="{ 'pager-text-disabled': !canGoPrev }"
                  >Previous</span
                >
              </span>
            </button>
            <span class="pager-counter">{{ safeIndex + 1 }} of {{ total }}</span>
            <button
              type="button"
              class="pager-button"
              :class="{ 'pager-button-disabled': !canGoNext }"
              :disabled="!canGoNext"
              @click="next"
            >
              <span class="pager-inner">
                <span
                  class="pager-text"
                  :class="{ 'pager-text-disabled': !canGoNext }"
                  >Next</span
                >
                <span
                  class="pager-glyph"
                  :class="{ 'pager-glyph-disabled': !canGoNext }"
                  >▶</span
                >
              </span>
            </button>
          </div>

          <div v-if="currentDelivery" class="delivery-card">
            <div class="section-card">
              <h3 class="section-heading">Summary</h3>
              <div class="detail-row">
                <span class="detail-label">Order Id</span>
                <span class="detail-value-mono">{{ orderIdDisplay(currentDelivery) }}</span>
              </div>
<!--              <div class="detail-row">-->
<!--                <span class="detail-label">Earnings</span>-->
<!--                <span class="detail-value detail-value-teal">{{-->
<!--                  formatOrderTotal(currentDelivery)-->
<!--                }}</span>-->
<!--              </div>-->
              <div class="detail-row-last">
                <span class="detail-label">Status</span>
                <div class="status-badge-wrap">
                  <span
                    class="status-badge"
                    :class="getStatusBadgeClass(currentDelivery.status)"
                    >{{ formatStatusLabel(currentDelivery.status) }}</span
                  >
                </div>
              </div>
            </div>

            <div v-if="currentDelivery.restaurant" class="section-card">
              <h3 class="section-heading">Pickup</h3>
              <p class="body-text-strong">{{ currentDelivery.restaurant.name }}</p>
              <p v-if="currentDelivery.restaurant.address" class="body-text-muted">
                {{ currentDelivery.restaurant.address
                }}{{
                  currentDelivery.restaurant.postcode
                    ? `, ${currentDelivery.restaurant.postcode}`
                    : ''
                }}
              </p>

              <button
                v-if="currentDelivery.restaurant.mobile"
                type="button"
                class="phone-row"
                @click="makePhoneCall(currentDelivery.restaurant.mobile)"
              >
                <span class="phone-icon">📞</span>
                <span class="phone-label">Restaurant</span>
                <span class="phone-number">{{ currentDelivery.restaurant.mobile }}</span>
              </button>

              <button
                type="button"
                class="pickup-button-small"
                :disabled="processingOrderId === currentDelivery.id"
                @click="openPickupInMaps(currentDelivery.restaurant)"
              >
                <span class="small-inner">
                  <span class="small-glyph">🗺</span>
                  <span class="pickup-text">Take me to pickup</span>
                </span>
              </button>
            </div>

            <div class="section-card">
              <h3 class="section-heading">Drop-off</h3>
              <p class="body-text-strong">{{ customerName(currentDelivery) }}</p>
              <p class="body-text-muted">
                {{ currentDelivery.address
                }}{{
                  currentDelivery.postcode
                    ? `, ${currentDelivery.postcode}`
                    : ''
                }}
              </p>

