                v-if="currentDelivery.customer_mobile"
                type="button"
                class="phone-row"
                @click="makePhoneCall(currentDelivery.customer_mobile)"
              >
                <span class="phone-icon">📞</span>
                <span class="phone-label">Customer</span>
                <span class="phone-number">{{ currentDelivery.customer_mobile }}</span>
              </button>

              <button
                type="button"
                class="pickup-button-small"
                :disabled="processingOrderId === currentDelivery.id"
                @click="openDropoffInMaps(currentDelivery)"
              >
                <span class="small-inner">
                  <span class="small-glyph">📍</span>
                  <span class="pickup-text">Take me to drop off</span>
