            >
              <button
                type="button"
                class="picked-up-button"
                :disabled="processingOrderId === currentDelivery.id"
                @click="handleOrderPickedUp(currentDelivery.id)"
              >
                <span
                  v-if="processingOrderId === currentDelivery.id"
                  class="btn-spin-white"
                />
                <span v-else class="small-inner">
