<script>
import ApiService from '../services/api';
import { formatOrderTotal, orderIdDisplay } from '../utils/orderFormat';

export default {
  name: 'OngoingOrdersView',
  data() {
    return {
      deliveries: [],
      loading: true,
      refreshing: false,
      processingOrderId: null,
      currentIndex: 0,
    };
  },
  computed: {
    total() {
      return this.deliveries.length;
    },
    safeIndex() {
      const t = this.total;
      if (t <= 0) return 0;
      return Math.min(this.currentIndex, t - 1);
    },
    currentDelivery() {
      if (this.total <= 0) return undefined;
      return this.deliveries[this.safeIndex];
    },
    canGoPrev() {
      return this.total > 0 && this.safeIndex > 0;
    },
    canGoNext() {
      return this.total > 0 && this.safeIndex < this.total - 1;
    },
  },
  watch: {
    deliveries(val) {
      if (val.length === 0) {
        this.currentIndex = 0;
      } else {
        this.currentIndex = Math.min(this.currentIndex, val.length - 1);
      }
    },
  },
  mounted() {
    this.fetchOngoingOrders();
  },
  methods: {
    formatOrderTotal,
    orderIdDisplay,
    customerName(item) {
      const n = item.customer_name && item.customer_name.trim();
      return n || 'Customer';
    },
    formatStatusLabel(status) {
      return String(status).replace('_', ' ').toUpperCase();
    },
    getStatusBadgeClass(status) {
      switch (status) {
        case 'assigned':
          return 'assigned-badge';
        case 'picking_up':
          return 'picking-up-badge';
        case 'in_progress':
          return 'in-progress-badge';
        default:
          return 'assigned-badge';
      }
    },
    async fetchOngoingOrders() {
      try {
        const response = await ApiService.get('/driver/deliveries/ongoing');

        let deliveriesList = [];

        if (response.success !== false) {
          if (response.deliveries) {
            deliveriesList = response.deliveries;
          } else if (response.data && response.data.deliveries) {
            deliveriesList = response.data.deliveries;
          } else if (Array.isArray(response.data)) {
            deliveriesList = response.data;
          } else if (Array.isArray(response)) {
            deliveriesList = response;
          }

          const ongoingOrders = deliveriesList.filter(
            (delivery) =>
              delivery.status === 'picking_up' ||
              delivery.status === 'in_progress'
          );
          this.deliveries = ongoingOrders;
        } else {
          window.alert(response.message || 'Failed to load orders');
        }
      } catch (error) {
        console.error('Error fetching orders:', error);
        window.alert(error.message || 'Failed to load orders');
      } finally {
        this.loading = false;
        this.refreshing = false;
      }
    },
    onRefresh() {
      this.refreshing = true;
      this.fetchOngoingOrders();
    },
    openPickupInMaps(restaurant) {
      if (!restaurant) return;

      const address = `${restaurant.address}, ${restaurant.postcode}`;

      const url = `geo:0,0?q=${encodeURIComponent(address)}`;

      window.location.href = url;
    },
    openDropoffInMaps(delivery) {
      const address = `${delivery.address}, ${delivery.postcode}`;
      const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(
        address
      )}`;
      window.open(url, '_blank', 'noopener,noreferrer');
    },
    makePhoneCall(phoneNumber) {
      if (!phoneNumber) return;
      const cleaned = String(phoneNumber).replace(/[\s\-()]/g, '');
      Android.makePhoneCall(cleaned);
    },
    handleOrderPickedUp(deliveryId) {
      if (this.processingOrderId === deliveryId) return;
      if (
        !window.confirm(
          'Have you picked up this order from the restaurant?'
        )
      ) {
        return;
      }
      this.processingOrderId = deliveryId;
      ApiService.put(`/driver/deliveries/${deliveryId}/status`, {
        status: 'in_progress',
      })
        .then((response) => {
          if (response.success !== false) {
            return this.fetchOngoingOrders().then(() => {
              window.alert(
                'Order marked as picked up! Status changed to In Progress.'
              );
            });
          }
          window.alert(response.message || 'Failed to update order status');
        })
        .catch((error) => {
          console.error('Error updating order status:', error);
          window.alert(error.message || 'Failed to update order status');
        })
        .finally(() => {
          this.processingOrderId = null;
        });
    },
    handleDeliveryCompleted(deliveryId) {
      if (this.processingOrderId === deliveryId) return;
      if (!window.confirm('Are you sure you have completed this delivery?')) {
        return;
      }
      this.processingOrderId = deliveryId;
      ApiService.put(`/driver/deliveries/${deliveryId}/complete`, {})
        .then((response) => {
          if (response.success !== false) {
            return this.fetchOngoingOrders().then(() => {
              window.alert('Delivery marked as completed!');
            });
          }
          window.alert(response.message || 'Failed to complete delivery');
        })
        .catch((error) => {
          console.error('Error completing delivery:', error);
          window.alert(error.message || 'Failed to complete delivery');
        })
        .finally(() => {
          this.processingOrderId = null;
        });
    },
    prev() {
      if (this.canGoPrev) this.currentIndex -= 1;
    },
    next() {
      if (this.canGoNext) this.currentIndex += 1;
    },
  },
};
</script>

